SELECT * FROM tb_purchase
WHERE platform       = #{platform}
  AND transaction_id = #{transactionId}
LIMIT 1

SELECT COUNT(*) > 0
FROM tb_purchase
WHERE platform       = #{platform}
  AND transaction_id = #{transactionId}

SELECT * FROM tb_purchase
WHERE user_seq = #{userSeq}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

